import React, { MouseEvent, PropsWithChildren, useContext } from 'react';
import { useIntl } from 'react-intl';
import type { Column } from 'react-table';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { ActionGroup } from '../../../../layouts/app-header/action-group/ActionGroup.js';
import { DataTableContext } from '../../../contexts/DataTableContext.js';
import {
  DATA_TABLE_ACTION_COLUMN_ID,
  DEFAULT_WIDTH_OF_ACTION_COLUMN,
} from '../../../DataTable/constants.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import { SingleColumn, TableRow } from '../../../types/shared-table-types.js';
import { _convertColumn } from '../../../types/table-type-mappings.js';
import { isActionColumn } from '../../../utils/column-utils.js';
import { RowActionsProvider } from '../useUserActions.types.js';

/**
 * This column is added by default if a DataTable.RowActions template
 * is present. If you want to override certain elements, like
 * width, you can use this constant as a starting point. See
 * example in documentation.
 */
export const DEFAULT_ROW_ACTIONS_COLUMN: SingleColumn = {
  id: DATA_TABLE_ACTION_COLUMN_ID,
  accessor: DATA_TABLE_ACTION_COLUMN_ID,
  header: undefined,
  width: DEFAULT_WIDTH_OF_ACTION_COLUMN,
  alignment: 'center',
  disableSortBy: true,
};

const ActionColumnCell = /* @__PURE__ */ styled('div')<{
  $density: 'default' | 'condensed' | 'comfortable';
}>((props) => {
  if (props.$density === 'default') {
    return {
      paddingTop: Spacings.Size6,
      paddingBottom: Spacings.Size6,
      paddingLeft: Spacings.Size12,
      paddingRight: Spacings.Size12,
    };
  } else if (props.$density === 'comfortable') {
    return {
      paddingTop: Spacings.Size8,
      paddingBottom: Spacings.Size8,
      paddingLeft: Spacings.Size16,
      paddingRight: Spacings.Size16,
    };
  } else if (props.$density === 'condensed') {
    return {
      paddingTop: Spacings.Size0,
      paddingBottom: Spacings.Size0,
      paddingLeft: Spacings.Size6,
      paddingRight: Spacings.Size6,
    };
  }

  return {};
});

export interface TableRowActionsProps {
  children: (row: TableRow) => JSX.Element | null;
}

export type DataTableRowActionsItemProps = PropsWithChildren<{
  onClick: () => void;
  prefixIcon: JSX.Element;
}>;

export type DataTableRowActionsGroupProps = PropsWithChildren;

/**
 * Configuration component used for defining row actions.
 * This component can only be used as a child element of `<DataTable.UserActions>`.
 */
export const RowActions = ({ children }: TableRowActionsProps) => {
  // eslint-disable-next-line react/jsx-no-useless-fragment
  return <>{children}</>;
};

const _TableRowActions = {};

export const Group = (props: DataTableRowActionsGroupProps) => {
  const { children, ...remainingProps } = props;
  const { variant } = useContext(DataTableContext);
  const density = variant.rowDensity ?? 'default';

  return (
    <ActionColumnCell $density={density}>
      <ActionGroup
        collapseFrom="end"
        justifyContent="center"
        density={density === 'condensed' ? 'condensed' : 'default'}
        {...remainingProps}
      >
        {children}
      </ActionGroup>
    </ActionColumnCell>
  );
};

// eslint-disable-next-line react/jsx-no-useless-fragment
export const Item = (props: DataTableRowActionsItemProps) => {
  const { variant } = useContext(DataTableContext);
  const density = variant.rowDensity === 'condensed' ? 'condensed' : 'default';
  const { children, onClick, prefixIcon, ...remainingProps } = props;

  const buttonClick = (event: MouseEvent) => {
    onClick();
  };

  return (
    <ActionGroup.ActionButton
      prefixIcon={prefixIcon}
      onClick={buttonClick}
      density={density}
      {...remainingProps}
    >
      {children}
    </ActionGroup.ActionButton>
  );
};

/**
 * Prepares actions column to be added to table.
 * @param label - column header label from i18n. However, if a string Header is provided by
 * the consumer (see DEFAULT_ROW_ACTIONS_COLUMN), that will be used.
 * @param rowActionsProvider - Factory function which is expected to return a component for a row.
 * @param existingColumn - column if there is one defined by the consumer to override values.
 * @returns prepared action column
 */
export function prepareActionColumn(
  rowActionsProvider: RowActionsProvider,
  existingColumn: Column<any> | undefined, // eslint-disable-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): Column<any> {
  const defaultCol = {
    ..._convertColumn(DEFAULT_ROW_ACTIONS_COLUMN),
    Header() {
      const intl = useIntl();
      return intl.formatMessage(dataTableMessages.actionColumnHeader);
    },
    Cell: (remainingColumn) => {
      return (
        <>
          {_convertRowActionsProvider(rowActionsProvider)({
            ...remainingColumn,
            // @ts-expect-error Does not 100% overlap with the type we exported and commited to
            // so this is a bit of a workaround and will no longer happen in DataTableV2
            index: remainingColumn.row.index,
            original: remainingColumn.rows[remainingColumn.row.index],
            values: remainingColumn.rows[remainingColumn.row.index].original,
          })}
        </>
      );
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } as Column<any>;
  if (existingColumn === undefined || existingColumn === null) {
    return defaultCol;
  }
  const { id, accessor, Header, ...propsToOverride } = existingColumn;
  if (typeof Header === 'string') {
    return { ...defaultCol, ...propsToOverride, Header };
  }
  return { ...defaultCol, ...propsToOverride };
}

/**
 * Maps from our API type to react-table type.
 * @param rowActionsProvider - API type
 * @returns react-table type
 */
function _convertRowActionsProvider(rowActionsProvider: RowActionsProvider) {
  // TODO improvement for future: proper API type mapping from/to react-table types
  return rowActionsProvider as (props: { row: TableRow }) => React.ReactElement;
}

/**
 * Finds if there is an overridden default actions column.
 * @param columns - all columns
 * @returns column and index or else undefined values
 */
export function findDefaultActionColumn(
  columns: Column<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): [defaultCol: Column<any> | undefined, defaultColIndex: number | undefined] {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let defaultCol: Column<any> | undefined = undefined;
  let defaultColIndex: number | undefined = undefined;
  for (let i = 0; i < columns.length; i++) {
    const col = columns[i];
    if (col.id && isActionColumn(col.id)) {
      defaultCol = col as Column<any>; // eslint-disable-line @typescript-eslint/no-explicit-any
      defaultColIndex = i;
      break;
    }
  }

  return [defaultCol, defaultColIndex];
}

/**
 * Creates an updated columns array containing the action column.
 * @param columns - original columns
 * @param actionColumn - new action column
 * @param defaultColIndex - index of column for override
 * @returns new columns array
 */
export function getUpdatedColumnsArray(
  columns: Column<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
  actionColumn: Column<any>, // eslint-disable-line @typescript-eslint/no-explicit-any
  defaultColIndex: number | undefined,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): Column<any>[] {
  const newColumns = [...columns];
  if (defaultColIndex) {
    newColumns[defaultColIndex] = actionColumn;
  } else {
    newColumns.push(actionColumn);
  }

  return newColumns;
}

export const TableRowActions = Object.assign(_TableRowActions, {
  Group,
  Item,
});

RowActions.displayName = 'DataTable.RowActions';
